-- FlexiLog Exercises Database Authoritative Overhaul - Non-Duplicate Custom Data
-- Generated on 2026-05-28

-- 1. Drop existing muscle_group constraint if exists to support new groups
ALTER TABLE exercises DROP CONSTRAINT IF EXISTS exercises_muscle_group_check;

-- 2. Create updated muscle_group constraint supporting 12 muscle groups
ALTER TABLE exercises ADD CONSTRAINT exercises_muscle_group_check 
  CHECK (muscle_group IN ('chest', 'back', 'legs', 'shoulders', 'biceps', 'triceps', 'core', 'full_body', 'glutes', 'forearms', 'traps', 'cardio'));

-- 3. Add equipment column if not exists
ALTER TABLE exercises ADD COLUMN IF NOT EXISTS equipment TEXT CHECK (equipment IN ('杠铃', '哑铃', '绳索', '器械', '自重', '壶铃', '其他'));

