UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手紧握阻力把手。配合呼吸，缓慢地拉起或推起重量，动作顶点主动挤压肌肉，随后控制速度放回。', tips = '动作全程保持核心紧张，下放速度要慢，切勿耸肩借力或依靠惯性甩动重量。', equipment = '其他', rest_seconds = 90 WHERE id = '715d2e19-64a7-40c5-a4a2-6e71fdac0653'; -- Name: 21响礼炮
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手以略宽于肩的闭合正手握法紧抓杠铃杆。双手紧握重物，手肘贴住身体；呼气肱二头肌发力弯举重量，前臂靠近大臂，顶部极力收缩二头肌；吸气控制下放速度，缓慢将重力落回至手臂伸直。', tips = '前臂向外翻转（旋后）能获得更好的二头挤压；手肘要时刻锁在两侧，身体不能前后摇晃借力。', equipment = '杠铃', rest_seconds = 120 WHERE id = '316e1008-044e-4f74-89da-42709d1851f4'; -- Name: Barbell Curl
