UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手紧握阻力把手。调整好器械姿势与心肺负荷，核心微微收紧保护脊柱；保持稳定而均匀的有氧呼吸，有节奏地持续运动，直至规定运动时间。', tips = '脚掌落地时关节要微屈缓冲，严禁双膝内扣，运动过程中上身不要过度松垮，维持良好体态。', equipment = '自重', rest_seconds = 60 WHERE id = 'c0ddaf09-efc6-4d20-895e-e102bb645069'; -- Name: 高抬腿
UPDATE exercises SET description = '平躺在训练平凳上，后脑勺、上背部、臀部以及双脚踩地保持稳定五点接触。双手以略宽于肩的闭合正手握法紧抓杠铃杆。吸气控制阻力，缓慢将重量下放至胸口位置，前臂保持垂直地面；呼气胸大肌发力，将重量推起至双臂几乎伸直，顶部用力挤压胸肌，手肘切勿锁死。', tips = '始终维持肩胛骨后缩下沉，起杠及推起过程中严禁耸肩以防止斜方肌代偿，推至顶部不要大力撞击。', equipment = '杠铃', rest_seconds = 120 WHERE id = 'e25c08a0-7d59-41ed-ac2e-fc522728ee7b'; -- Name: Bench Press
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手分别握住拉杆或双头绳索末端卡扣。手臂微屈约15度并锁死肘关节；呼气胸大肌发力，沿弧线轨迹将重量向前夹拢，使双手在胸前相遇；吸气控制阻力，缓慢将双臂沿弧线放回起始位置。', tips = '动作全程务必固定肘关节角度，用大臂靠拢的感觉带动夹胸，切勿借力做成推胸。', equipment = '绳索', rest_seconds = 60 WHERE id = '5fbe3e6d-0dba-4682-bdbe-745ba92cf676'; -- Name: Cable Flyes
UPDATE exercises SET description = '坐在30-45度倾角的训练椅上，双脚平放地面踩实，肩胛骨向后收紧下沉。双手持哑铃置于大腿或身体两侧，手腕保持中立稳定。吸气控制阻力，缓慢将重量下放至胸口位置，前臂保持垂直地面；呼气胸大肌发力，将重量推起至双臂几乎伸直，顶部用力挤压胸肌，手肘切勿锁死。', tips = '始终维持肩胛骨后缩下沉，起杠及推起过程中严禁耸肩以防止斜方肌代偿，推至顶部不要大力撞击。', equipment = '哑铃', rest_seconds = 90 WHERE id = '665ba408-51ed-4c9e-afc8-ab3b706d7315'; -- Name: Incline Dumbbell Press
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手紧握阻力把手。双手比肩略宽支撑，核心收紧；吸气缓慢将身体放低至胸部几乎触地，大臂与躯干呈45度夹角；呼气胸肌与三头肌发力，将身体推回原位。', tips = '整个过程头部、脊柱与骨盆保持中立，臀部不能下塌或高耸，避免大臂向两侧打得过开伤害肩膀。', equipment = '其他', rest_seconds = 90 WHERE id = 'fd0d547c-3ea6-4e5a-9bf5-a1d83e054130'; -- Name: Push-ups
UPDATE exercises SET description = '坐在30-45度倾角的训练椅上，双脚平放地面踩实，肩胛骨向后收紧下沉。双手紧握阻力把手。双手比肩略宽支撑，核心收紧；吸气缓慢将身体放低至胸部几乎触地，大臂与躯干呈45度夹角；呼气胸肌与三头肌发力，将身体推回原位。', tips = '整个过程头部、脊柱与骨盆保持中立，臀部不能下塌或高耸，避免大臂向两侧打得过开伤害肩膀。', equipment = '自重', rest_seconds = 60 WHERE id = 'ea8d3c9d-87c1-4b84-8889-f0710f2a2a2c'; -- Name: 上斜俯卧撑
UPDATE exercises SET description = '躺在下斜板上，双脚牢牢卡住固定垫，保持核心与臀部收紧，肩胛下压。双手紧握阻力把手。双手比肩略宽支撑，核心收紧；吸气缓慢将身体放低至胸部几乎触地，大臂与躯干呈45度夹角；呼气胸肌与三头肌发力，将身体推回原位。', tips = '整个过程头部、脊柱与骨盆保持中立，臀部不能下塌或高耸，避免大臂向两侧打得过开伤害肩膀。', equipment = '自重', rest_seconds = 60 WHERE id = '6ba46cfa-ad99-47b7-a43e-d5c9faaca20a'; -- Name: 下斜俯卧撑
UPDATE exercises SET description = '平躺在训练平凳上，后脑勺、上背部、臀部以及双脚踩地保持稳定五点接触。双手持哑铃置于大腿或身体两侧，手腕保持中立稳定。配合呼吸，缓慢地拉起或推起重量，动作顶点主动挤压肌肉，随后控制速度放回。', tips = '动作全程保持核心紧张，下放速度要慢，切勿耸肩借力或依靠惯性甩动重量。', equipment = '哑铃', rest_seconds = 90 WHERE id = '82ed3585-e723-4f84-a9e4-e22f8faf9fcb'; -- Name: 仰卧哑铃直臂上拉
