UPDATE exercises SET description = '双手握住双杠，双臂伸直支撑身体，核心收紧，大腿微屈，小腿交叉悬空。双手紧握阻力把手。配合呼吸，缓慢地拉起或推起重量，动作顶点主动挤压肌肉，随后控制速度放回。', tips = '动作全程保持核心紧张，下放速度要慢，切勿耸肩借力或依靠惯性甩动重量。', equipment = '自重', rest_seconds = 60 WHERE id = 'b43ff699-9dea-4102-8cf4-f71f7f198e99'; -- Name: 双杠臂屈伸
