UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手紧握阻力把手。呼气核心与腹直肌发力，进行躯干的卷屈使胸椎靠近盆骨，在顶点极力挤压腹肌；吸气缓慢将躯干放低回拉伸位，背部保持微曲。', tips = '双手不要抱头生拉硬扯颈椎，专注于用腹部肌肉卷起上身，颈部保持放松。', equipment = '自重', rest_seconds = 60 WHERE id = 'cf46e17c-7b76-401e-9b51-ffcff4682b82'; -- Name: Ab轮卷腹
