UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手紧握阻力把手。配合呼吸，缓慢地拉起或推起重量，动作顶点主动挤压肌肉，随后控制速度放回。', tips = '动作全程保持核心紧张，下放速度要慢，切勿耸肩借力或依靠惯性甩动重量。', equipment = '其他', rest_seconds = 90 WHERE id = '939b981b-3f55-4bca-8e40-448789cb666a'; -- Name: 跪姿后踢腿
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手紧握阻力把手。吸气屈膝，控制阻力缓慢将挡板压低至膝关节呈90度夹角；呼气股四头肌发力将踏板推回原位；顶部保持膝关节微屈，切勿撞击或完全锁死膝盖。', tips = '脚底和臀大肌必须全程压实踏板和椅背，严禁脚跟抬起或下背悬空，否则会导致骨盆后倾受伤。', equipment = '其他', rest_seconds = 90 WHERE id = 'f6f9d0f6-69a6-4d32-9c1b-7f076a7a3eee'; -- Name: 45度腿举
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手紧握阻力把手。配合呼吸，缓慢地拉起或推起重量，动作顶点主动挤压肌肉，随后控制速度放回。', tips = '动作全程保持核心紧张，下放速度要慢，切勿耸肩借力或依靠惯性甩动重量。', equipment = '其他', rest_seconds = 90 WHERE id = 'c48b15e7-9116-4058-adb3-fcb014d441f6'; -- Name: Calf Raises
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手紧握阻力把手。抓紧握柄，呼气收紧腘绳肌发力弯起小腿，使圆垫移向臀部并在此顶峰收缩1秒；吸气缓慢将重物放回起始位置。', tips = '臀部和骨盆必须牢牢压紧在软垫上面，不要随着弯举翘起屁股或弯腰借力。', equipment = '器械', rest_seconds = 90 WHERE id = '3eea923b-66ec-45d8-8a87-a075684e9349'; -- Name: Leg Curl
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手紧握阻力把手。吸气屈膝，控制阻力缓慢将挡板压低至膝关节呈90度夹角；呼气股四头肌发力将踏板推回原位；顶部保持膝关节微屈，切勿撞击或完全锁死膝盖。', tips = '脚底和臀大肌必须全程压实踏板和椅背，严禁脚跟抬起或下背悬空，否则会导致骨盆后倾受伤。', equipment = '器械', rest_seconds = 90 WHERE id = '69dbf47d-c941-40d4-a816-d3742ca403c0'; -- Name: Leg Press
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手以略宽于肩的闭合正手握法紧抓杠铃杆。膝关节微屈并锁定，维持核心收紧；屈髋发力将臀部往正后方推送，使上身前倾下放重量，保持重量贴沿腿下滑至小腿中段；呼气臀大肌前推直立，顶部收紧臀肌。', tips = '重点在于髋部的后推前后移动，而非下蹲；脊柱必须全程维持挺直中立以防下背部受伤。', equipment = '杠铃', rest_seconds = 120 WHERE id = 'e827a108-ed12-4e3c-9e7f-7a1d42d326b1'; -- Name: Romanian Deadlift
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手以略宽于肩的闭合正手握法紧抓杠铃杆。吸气核心收紧，启动屈髋屈膝动作，臀部如坐凳子般向下后方降低；下蹲至大腿与地面平行或略低，膝盖与脚尖方向一致；呼气脚底用力蹬地伸膝伸髋直立起立。', tips = '下蹲时膝盖方向绝对不能内扣，需始终朝向脚尖；背部和腰部绝对不能弯曲，保持中立脊柱。', equipment = '杠铃', rest_seconds = 120 WHERE id = '8538898f-9fdc-43c6-b1b9-8d685062152d'; -- Name: Squat
