UPDATE exercises SET description = '坐在固定座椅上，调整座椅高度，腰椎自然挺直，大腿被挡垫稳固固定，双脚踩实。双手紧握阻力把手。配合呼吸，缓慢地拉起或推起重量，动作顶点主动挤压肌肉，随后控制速度放回。', tips = '动作全程保持核心紧张，下放速度要慢，切勿耸肩借力或依靠惯性甩动重量。', equipment = '器械', rest_seconds = 90 WHERE id = '72ae72d0-43b4-4dfc-b35e-e8741621201d'; -- Name: 坐姿提踵
UPDATE exercises SET description = '坐在固定座椅上，调整座椅高度，腰椎自然挺直，大腿被挡垫稳固固定，双脚踩实。双手紧握阻力把手。抓紧握柄，呼气收紧腘绳肌发力弯起小腿，使圆垫移向臀部并在此顶峰收缩1秒；吸气缓慢将重物放回起始位置。', tips = '臀部和骨盆必须牢牢压紧在软垫上面，不要随着弯举翘起屁股或弯腰借力。', equipment = '器械', rest_seconds = 90 WHERE id = '998724dc-bf47-4fb4-aa0a-6235e21980ce'; -- Name: 坐姿腿弯举
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手以略宽于肩的闭合正手握法紧抓杠铃杆。配合呼吸，缓慢地拉起或推起重量，动作顶点主动挤压肌肉，随后控制速度放回。', tips = '动作全程保持核心紧张，下放速度要慢，切勿耸肩借力或依靠惯性甩动重量。', equipment = '杠铃', rest_seconds = 120 WHERE id = '87c9c9a8-43db-402c-b139-c0e9350c35f8'; -- Name: 杠铃前蹲
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手以略宽于肩的闭合正手握法紧抓杠铃杆。吸气核心收紧，启动屈髋屈膝动作，臀部如坐凳子般向下后方降低；下蹲至大腿与地面平行或略低，膝盖与脚尖方向一致；呼气脚底用力蹬地伸膝伸髋直立起立。', tips = '下蹲时膝盖方向绝对不能内扣，需始终朝向脚尖；背部和腰部绝对不能弯曲，保持中立脊柱。', equipment = '杠铃', rest_seconds = 120 WHERE id = 'f4ec05fa-fae5-4d99-a3f0-b466779d3267'; -- Name: 杠铃深蹲
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手以略宽于肩的闭合正手握法紧抓杠铃杆。配合呼吸，缓慢地拉起或推起重量，动作顶点主动挤压肌肉，随后控制速度放回。', tips = '动作全程保持核心紧张，下放速度要慢，切勿耸肩借力或依靠惯性甩动重量。', equipment = '杠铃', rest_seconds = 120 WHERE id = '87e64ca7-c85e-4f2f-b372-54fcb6c6dd59'; -- Name: 杠铃箭步蹲
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手紧握阻力把手。屈髋屈膝下蹲，双手握杆；核心锁死，挺胸，足中足跟踩地发力，腿部与背部协同将重量拉起，保持重量紧贴腿面，至身体完全直立锁定髋关节；沿腿部缓慢屈髋下放。', tips = '拉起过程中脊柱绝不能拱起或曲挠，杠铃杆严禁离开身体，手臂完全伸直充当拉线，不可耸肩。', equipment = '其他', rest_seconds = 120 WHERE id = 'cc5b6a35-725e-4e50-ab2f-a0a3daf6204d'; -- Name: 直腿硬拉
UPDATE exercises SET description = '自然直立站稳，双脚与肩同宽，膝关节微屈避免锁死，核心与臀肌强烈收紧。双手紧握阻力把手。配合呼吸，缓慢地拉起或推起重量，动作顶点主动挤压肌肉，随后控制速度放回。', tips = '动作全程保持核心紧张，下放速度要慢，切勿耸肩借力或依靠惯性甩动重量。', equipment = '器械', rest_seconds = 90 WHERE id = '3f5ff712-c4dc-4ac5-a259-32f621cdc54c'; -- Name: 站姿提踵
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手紧握阻力把手。膝关节微屈并锁定，维持核心收紧；屈髋发力将臀部往正后方推送，使上身前倾下放重量，保持重量贴沿腿下滑至小腿中段；呼气臀大肌前推直立，顶部收紧臀肌。', tips = '重点在于髋部的后推前后移动，而非下蹲；脊柱必须全程维持挺直中立以防下背部受伤。', equipment = '其他', rest_seconds = 120 WHERE id = 'c2ace4c8-d601-4955-a0fc-8f34d6ac7533'; -- Name: 罗马尼亚硬拉
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手紧握阻力把手。吸气屈膝，控制阻力缓慢将挡板压低至膝关节呈90度夹角；呼气股四头肌发力将踏板推回原位；顶部保持膝关节微屈，切勿撞击或完全锁死膝盖。', tips = '脚底和臀大肌必须全程压实踏板和椅背，严禁脚跟抬起或下背悬空，否则会导致骨盆后倾受伤。', equipment = '其他', rest_seconds = 90 WHERE id = '75d9cf8a-7f44-4c8b-a064-de1a70530707'; -- Name: 腿举
