UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手分别握住拉杆或双头绳索末端卡扣。配合呼吸，缓慢地拉起或推起重量，动作顶点主动挤压肌肉，随后控制速度放回。', tips = '动作全程保持核心紧张，下放速度要慢，切勿耸肩借力或依靠惯性甩动重量。', equipment = '绳索', rest_seconds = 60 WHERE id = '4c8e6ad9-e138-4c81-a9da-325bf061755c'; -- Name: Face Pulls
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手持哑铃置于大腿或身体两侧，手腕保持中立稳定。双肘保持微屈10度并固定；呼气三角肌中束发力，将手臂向两侧弧线抬起，直至大臂与地面平行；吸气控制重力将重量放回大腿两侧。', tips = '动作全程大拇指微朝下或手腕略低于肘部，三角肌发力，切勿耸肩以免斜方肌代偿。', equipment = '哑铃', rest_seconds = 90 WHERE id = 'ac0baefb-97b6-426c-a676-abb9bd65103c'; -- Name: Lateral Raises
UPDATE exercises SET description = '自然直立站稳，双脚与肩同宽，膝关节微屈避免锁死，核心与臀肌强烈收紧。双手以略宽于肩的闭合正手握法紧抓杠铃杆。呼气肩部三角肌发力，将重量垂直向上推起至手臂完全伸直，头部微后仰以避开轨迹；吸气控制阻力，将重量缓慢下放至肩颈位置。', tips = '推至顶部时手肘可以伸直但不要撞击或完全锁死锁死；腹肌和臀肌要始终夹紧，防止腰椎超展挺腰。', equipment = '杠铃', rest_seconds = 120 WHERE id = '4a354dee-aea8-4171-9e52-4fdead2e9865'; -- Name: Overhead Press
UPDATE exercises SET description = '双脚同肩宽站立，屈髋下腰使上身呈约45度倾角，背部挺直，核心完全锁死。双手持哑铃置于大腿或身体两侧，手腕保持中立稳定。配合呼吸，缓慢地拉起或推起重量，动作顶点主动挤压肌肉，随后控制速度放回。', tips = '动作全程保持核心紧张，下放速度要慢，切勿耸肩借力或依靠惯性甩动重量。', equipment = '哑铃', rest_seconds = 90 WHERE id = 'ad504560-5311-41da-b3ac-17305b72384d'; -- Name: 俯身哑铃飞鸟
