UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手紧握阻力把手。双手持重物双臂伸直，大臂微往头部方向倾斜；吸气保持大臂绝对固定，屈肘将重量下放至额头或发际线位置；呼气三头肌发力将手臂推直还原。', tips = '手肘必须在动作过程中保持向内夹紧，不能向两侧过度张开，防止负荷转移到关节上。', equipment = '器械', rest_seconds = 90 WHERE id = 'e02c53c7-a1d0-4b7a-85ef-5d3d94c1b75e'; -- Name: 器械臂屈伸
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手紧握阻力把手。配合呼吸，缓慢地拉起或推起重量，动作顶点主动挤压肌肉，随后控制速度放回。', tips = '动作全程保持核心紧张，下放速度要慢，切勿耸肩借力或依靠惯性甩动重量。', equipment = '其他', rest_seconds = 90 WHERE id = '79dc9083-434b-4949-b36c-856815a9cc21'; -- Name: 窄握卧推
UPDATE exercises SET description = '准备好器械，身体保持稳定状态，核心收紧。双手分别握住拉杆或双头绳索末端卡扣。双手握住拉绳，手肘弯曲成90度紧贴身体；呼气肱三头肌发力，将前臂垂直向下压至手臂完全伸直，底部极力收缩三头肌；吸气控制拉力缓慢曲肘折回。', tips = '大臂和手肘在动作全程绝对不能发生任何晃动，肩膀放松，切勿用身体的重力压上去。', equipment = '绳索', rest_seconds = 60 WHERE id = 'da008b5c-60bc-4417-8772-5a749a5e4750'; -- Name: 绳索Y型下压
